function buildPEQData(type, freqIndex, gainIndex, qIndex, sIndex) {
  return (type & 7 | (freqIndex & 511) << 3 | (gainIndex & 255) << 12 | (qIndex & 127) << 20 | (sIndex & 31) << 27) >>> 0;
}
function freqToIndex(hz) {
  let best = 0;
  let bestDiff = Infinity;
  for (let i = 0; i < PEQ_FREQ_TABLE.length; i++) {
    const d = Math.abs(PEQ_FREQ_TABLE[i] - hz);
    if (d < bestDiff) {
      bestDiff = d;
      best = i;
    }
  }
  return best;
}
function parsePEQData(data) {
  return {
    type: data & 7,
    freq: data >> 3 & 511,
    gain: data >> 12 & 255,
    q: data >> 20 & 127,
    s: data >>> 27 & 31
  };
}
var MT2_LOW_DETENTS = [20, 50, 100, 200];
var MT2_HIGH_DETENTS = [1e3, 2e3, 5e3, 1e4];
var MT2_MIDFREQ_DETENTS = [200, 500, 1e3, 2e3];
function mt2DetentHz(n, detents) {
  const idx = Math.min(detents.length - 1, Math.max(0, Math.round(n * (detents.length - 1))));
  return detents[idx];
}
function mt2DetentNorm(hz, detents) {
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < detents.length; i++) {
    const d = Math.abs(detents[i] - hz);
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best / (detents.length - 1);
}
var MT2_REG60_NEUTRAL = buildPEQData(PEQ_TYPE.PEAK, freqToIndex(500), 120, 10, 10);
var mt2MidFreq = (n) => freqToIndex(mt2DetentHz(n, MT2_MIDFREQ_DETENTS));
var mt2LowFreq = (n) => freqToIndex(mt2DetentHz(n, MT2_LOW_DETENTS));
var mt2HighFreq = (n) => freqToIndex(mt2DetentHz(n, MT2_HIGH_DETENTS));
var mt2MidCompute = (n, cur) => {
  const p = parsePEQData(cur ?? MT2_REG60_NEUTRAL);
  return buildPEQData(PEQ_TYPE.PEAK, p.freq, clampPEGgain(120 + Math.round((n - 0.5) * 120)), p.q, p.s);
};
var mt2MidFreqCompute = (n, cur) => {
  const p = parsePEQData(cur ?? MT2_REG60_NEUTRAL);
  return buildPEQData(PEQ_TYPE.PEAK, mt2MidFreq(n), p.gain, p.q, p.s);
};
